// 两家的退款样本（用户 10-15 给的，已脱敏：单号、卡号、账号、商户名都是虚构的，长度和结构照真实数据）。
// 第 ③ 版（解析）用它测读得对不对；第 ④ 版（退款配原单）用 pairs 当预期结果。
//   支付宝：退款行是真实样本的结构（分类是「交通出行」不是「退款」，收/支是「不计收支」，单号 = 原单号_后缀）；
//           原单是补的，状态按需求文档假设为「交易成功、支出」，真实状态待以后核对。
//           Excel 打开后时间显示成 2026/10/4 15:52（月日不补零、没有秒），见 excelTime。
//   微信：退款行是真实样本的结构（退款行自己也带「已退款¥x」「已全额退款」状态，交易类型可能带商户全名，
//         对方名用全角括号，商户单号为空，备注「/」）；原单是补的，交易类型、商品、商户单号按常见写法假设，待核对。
//         退款单号和原单单号无关，不能按单号配对。
const B = require('../helpers/bills');
const T = (mo, d, h, mi, s) => ({ y: 2026, mo, d, h, mi, s });
const SHOP = '某某自助烤肉（示例万象天地店）';

const alipay = [
  B.txn({ time: T(9, 29, 10, 15, 32), kind: '交通出行', cp: '铁路12306', acct: 'abc***@alipay.com', desc: '火车票', io: 'expense', fen: 39600,
    pm: '示例银行信用卡(1234)', status: '交易成功', no: '2026092922001400000000000001', mno: 'M2026092900000001' }),
  B.txn({ time: T(10, 4, 15, 52, 7), kind: '交通出行', cp: '铁路12306', acct: 'abc***@alipay.com', desc: '退款-火车票', io: 'neutral', fen: 39600,
    pm: '示例银行信用卡(1234)', status: '退款成功', no: '2026092922001400000000000001_M20261004000000000001', mno: 'M2026092900000001' }),
];
const wechat = [
  B.txn({ time: T(9, 28, 12, 3, 11), kind: '商户消费', cp: '美团', desc: '美团订单', io: 'expense', fen: 2350,
    pm: '示例银行储蓄卡(5678)', status: '已退款¥0.90', no: '42000000002026092800000000001', mno: '10000000000000000000001' }),
  B.txn({ time: T(9, 29, 0, 58, 43), kind: '美团-退款', cp: '美团', desc: '美团', io: 'income', fen: 90,
    pm: '示例银行储蓄卡(5678)', status: '已退款¥0.90', no: '50300000002026092900000000001', mno: '' }),
  B.txn({ time: T(9, 28, 18, 40, 5), kind: '商户消费', cp: SHOP, desc: SHOP, io: 'expense', fen: 5000,
    pm: '示例银行信用卡(1234)', status: '已全额退款', no: '42000000002026092800000000002', mno: '10000000000000000000002' }),
  B.txn({ time: T(9, 28, 20, 22, 23), kind: SHOP + '-退款', cp: SHOP, desc: SHOP, io: 'income', fen: 5000,
    pm: '示例银行信用卡(1234)', status: '已全额退款', no: '50100000002026092800000000002', mno: '' }),
];
// 账单起止时间：覆盖上面所有交易
const range = { from: '2026-09-01 00:00:00', to: '2026-10-31 23:59:59' };
// Excel 打开另存后的时间写法：2026/10/4 15:52
const excelTime = t => `${t.y}/${t.mo}/${t.d} ${t.h}:${String(t.mi).padStart(2, '0')}`;
// 第 ④ 版的预期：退款行单号 → 应该挂到的原单单号
//   支付宝按单号开头（原单号_后缀）；微信按「时间在后、同对方、金额对得上、排除退款行自己」，各自唯一配上
const pairs = {
  alipay: { '2026092922001400000000000001_M20261004000000000001': '2026092922001400000000000001' },
  wechat: { '50300000002026092900000000001': '42000000002026092800000000001', '50100000002026092800000000002': '42000000002026092800000000002' },
};
// 1016-C 起：退款加起来正好等于原单（全额退款）的一对，两条都跳过（等于没发生），不再挂到原单上。
//   这里列出 pairs 里属于全额退款的退款行；其余（部分退款）照旧挂到原单
const full = {
  alipay: ['2026092922001400000000000001_M20261004000000000001'],
  wechat: ['50100000002026092800000000002'],
};
module.exports = { alipay, wechat, range, excelTime, pairs, full };
